 function invalidateVideoReviews(reviews,productKey,campaigns=[],jobs=[]){const campaignIds=campaigns.filter(c=>c.product_refs.includes(productKey)).map(c=>c.campaign_id),affected=new Set(campaignIds),revoked=[];const next=reviews.map(review=>{if(review.manifest.product_key!==productKey&&!affected.has(review.manifest.campaign_id))return review;if(review.decision==='APPROVED')revoked.push(review);return {...review,decision:'PENDING',approved_at:null};});const nextJobs=jobs.map(job=>job.product_ref!==productKey&&!affected.has(job.campaign_id)?job:core.validateAiSalesVideoJob({...copy(job),state:'QA_BLOCKED',error_code:'INPUTS_CHANGED_REPLAN_REQUIRED',output_hash:null,path_local:null}));return {reviews:next,revoked,jobs:nextJobs,campaignIds};}
