 async function validateReviewCampaign(manifest,campaign,products,assets){
  if(!campaign||campaign.campaign_id!==manifest.campaign_id||campaign.template_id!==manifest.template_id||!campaign.product_refs.includes(manifest.product_key))fail('AI_SALES_VIDEO_PLAN_NOT_FOUND');
  const replanned=await core.planAiSalesCampaign({campaign_id:campaign.campaign_id,products,assets,template_id:campaign.template_id,channel:campaign.channel,goal:campaign.goal,generated_at:campaign.generated_at});
  if(replanned.status!=='READY_FOR_LOCAL_RENDER'||core.canonicalAiSalesJson(replanned)!==core.canonicalAiSalesJson(campaign))fail('AI_SALES_VIDEO_CURRENT_PRODUCT_CHANGED');
  const expected=await core.createAiSalesVideoJob(campaign,manifest.product_key,{job_id:manifest.job.job_id,assets});
  if(expected.state!=='PLANNED'||expected.idempotency_key!==manifest.job.idempotency_key||core.canonicalAiSalesJson(expected.input_hashes)!==core.canonicalAiSalesJson(manifest.job.input_hashes))fail('AI_SALES_VIDEO_PLAN_MISMATCH');
  return true;
 }
