  const coverage=chosenCoverage(p),represented_units=coverage.reduce((sum,row)=>sum+row.quantity,0),total=[...imageFiles.values()].reduce((sum,f)=>sum+f.size,0)+files.reduce((sum,f)=>sum+f.size,0);if(total>67108864)fail('AI_SALES_ASSET_BYTES_LIMIT');
