   if(!safe(file.size)||file.size<1||file.size>8388608)fail('AI_SALES_IMAGE_SIZE_INVALID');const bytes=await file.arrayBuffer(),header=imageHeader(bytes);ensureSession(generation);
   if(header.width<16||header.height<16||header.width>4096||header.height>4096)fail('AI_SALES_IMAGE_DIMENSIONS_INVALID');
