   const sha256=await digest(bytes);ensureSession(generation);const prior=state.assets.find(a=>a.product_key===p.product_key&&a.sha256===sha256&&a.file_name===file.name),fileConflict=state.assets.find(a=>a.file_name===file.name&&a.sha256!==sha256);if(fileConflict||incoming.some(row=>row.asset.file_name===file.name&&row.asset.sha256!==sha256))fail('AI_SALES_FILENAME_BYTES_CONFLICT');
   const same=prior&&prior.role===role&&prior.rights.reference===reference&&core.canonicalAiSalesJson(prior.component_coverage)===core.canonicalAiSalesJson(coverage);
   const asset=core.validateAiSalesAsset(same?prior:{schema:'mls_ai_sales_asset_v1',asset_id:prior?.asset_id||'asset-'+uuid(),product_key:p.product_key,variant_ref:p.variant_ref,file_name:file.name,sha256,mime:header.mime,width:header.width,height:header.height,size_bytes:file.size,role,represented_units,component_coverage:coverage,origin:'LOCAL_OPERATOR',rights:{status:'AUTHORIZED',reference,observed_at:epoch()},preserve_geometry:true});
   if(incoming.some(row=>row.asset.asset_id===asset.asset_id||row.asset.sha256===asset.sha256&&row.asset.product_key===asset.product_key))fail('AI_SALES_DUPLICATE_ASSET_BYTES');incoming.push({file,asset,changed:!same});
