 function renderAssets(){const target=el('Assets');target.replaceChildren();for(const asset of state.assets){const card=node('article',undefined,'mls-ai-record'),media=node('div',undefined,'mls-ai-media'),url=imageUrls.get(asset.asset_id);if(url){const img=node('img');img.src=url;img.alt='Original vinculado: '+asset.file_name;media.append(img);}const content=node('div');content.append(node('h4',asset.file_name),node('p',(url?'Bytes reanexados':'Original ausente: reanexe o arquivo')+' · '+asset.width+' × '+asset.height+' px'),node('p',asset.represented_units+' peça(s) · '+asset.role+' · SHA-256 '+shortHash(asset.sha256)),node('p','Peças: '+(asset.component_coverage.map(row=>row.component_ref+' × '+row.quantity).join(' · ')||'Arte sem foto de produto')));media.append(content);card.append(media,button('Retirar imagem',()=>removeAsset(asset.asset_id)));target.append(card);}if(!state.assets.length)empty(target,'Vincule uma foto ou mockup original de cada peça vendida. A arte sozinha não substitui o produto.');}
 function campaignInputs(campaign){const products=campaign.product_refs.map(key=>selectedProduct(key));if(products.some(p=>!p))fail('AI_SALES_PLAN_PRODUCTS_CHANGED');const assets=campaign.asset_refs.map(id=>state.assets.find(a=>a.asset_id===id));if(assets.some(a=>!a||!imageFiles.has(a.asset_id)))fail('AI_SALES_ORIGINAL_BYTES_REQUIRED');return {products,assets};}
