  getSnapshot:()=>state,getChangeToken:()=>changeToken,hasLocalWork,
  validateWorkspace,now:epoch,isOffline:()=>globalThis.__mlsOfflineReview?.backend_mode==='READ_ONLY_SNAPSHOT',
