  el('PerformanceExport').onclick=()=>run(()=>download(core.exportAiSalesPerformance(state.performance,{format:'json'}),'mls-desempenho-ledger.json'));
  el('PerformanceTemplate').onclick=()=>run(()=>download(core.AI_SALES_PERFORMANCE_CSV_HEADERS.join(',')+'\r\n','mls-desempenho-cabecalho.csv','text/csv;charset=utf-8'));
  el('PerformanceForm').onsubmit=event=>{event.preventDefault();run(()=>{performanceReport=core.buildAiSalesPerformanceReport(state.performance,{provider:el('PerformanceProvider').value,shop_ref:el('PerformanceShop').value.trim(),source:el('PerformanceSource').value.trim(),currency:el('PerformanceCurrency').value.trim(),period:{start_date:el('PerformanceStart').value,end_date:el('PerformanceEnd').value},min_sample_orders:20});notice('Desempenho observado conferido. Dados declarados não comprovam lucro bancário ou um criativo vencedor.');});};
